        pt.groupby("fold", observed=False)["elpd_loo"]
        .agg([("n", "size"), ("elpd", "sum")])  # type: ignore[list-item]
        .reset_index()
    )
    vals = pt["elpd_loo"].to_numpy(float)
    return KFoldCV(
        fit.family,
        K,
        folds,
        group,
        joint,
        table,
        float(vals.sum()),
        float(np.sqrt(n * np.var(vals, ddof=1))) if n &gt; 1 else np.nan,
        None,
        False,
    )
